-- Replaces the circle-approximated AIP reference layer (0023) with real
-- polygons. Source: a community-maintained KML fetched via Google My Maps'
-- own export endpoint (https://www.google.com/maps/d/kml?mid=...) — "איסור
-- טיסה" by הארגון הישראלי לרב-להב (ICD, www.icd.org.il), last updated
-- 2025-12-19, whose own descriptions cite פמ"ת א'-17 (the CAAI aeronautical
-- publication) as their source per zone. Each zone's altitude_text below is
-- copied verbatim from that KML's own per-placemark description/name field,
-- not re-derived — so it inherits whatever accuracy the source has.
--
-- Still advisory-only (see 0023's comment for why): a third party's
-- digitization of official limits is not the same as the limits
-- themselves, so this must never feed find_intersecting_zones or any
-- automated clearance decision — the client renders it as a clearly
-- labeled, toggleable reference layer and nothing more.

alter table aip_reference_zones
  add column geom_geojson jsonb;

delete from aip_reference_zones;

alter table aip_reference_zones
  alter column geom_geojson set not null,
  drop column center_lng,
  drop column center_lat,
  drop column radius_m;

-- Seed data below: 91 zones (CTR/TMA/RESTRICTED/DANGER/PROHIBITED), deduped
-- by ICAO/LL code, preferring the source's more fully-described entries
-- (explicit "ft AMSL" citations) over terser duplicates where both exist.

